import React, { useState, useEffect, useCallback, useRef } from "react";
import "../styles/landingpage.css";
import { SLIDES_DATA } from "../../../database/models/listsfortesting";

const AUTOPLAY_DELAY = 5000;

const ArrowIcon = ({ direction }) => (
  <svg
    width="24"
    height="24"
    viewBox="0 0 24 24"
    fill="none"
    aria-hidden="true"
  >
    <path
      d={direction === "left" ? "M15 18L9 12L15 6" : "M9 18L15 12L9 6"}
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

const DiscoverIcon = () => (
  <svg
    width="20"
    height="20"
    viewBox="0 0 20 20"
    fill="none"
    aria-hidden="true"
  >
    <path
      d="M7.5 15L12.5 10L7.5 5"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
    />
  </svg>
);

export default function LandingPage() {
  const [currentSlide, setCurrentSlide] = useState(0);
  const [isAutoPlaying, setIsAutoPlaying] = useState(true);
  const timerRef = useRef(null);

  const nextSlide = useCallback(() => {
    setCurrentSlide((prev) => (prev + 1) % SLIDES_DATA.length);
  }, []);

  const prevSlide = useCallback(() => {
    setCurrentSlide(
      (prev) => (prev - 1 + SLIDES_DATA.length) % SLIDES_DATA.length
    );
  }, []);

  const goToSlide = useCallback((index) => {
    setCurrentSlide(index);
    setIsAutoPlaying(false);
  }, []);

  const handleDiscoverClick = useCallback(() => {
    console.log("Discover clicked for:", SLIDES_DATA[currentSlide].title);
    // Add your navigation logic here
  }, [currentSlide]);

  // Autoplay functionality
  useEffect(() => {
    if (!isAutoPlaying) return;

    timerRef.current = setInterval(nextSlide, AUTOPLAY_DELAY);

    return () => {
      if (timerRef.current) {
        clearInterval(timerRef.current);
      }
    };
  }, [isAutoPlaying, nextSlide]);

  // Pause autoplay on user interaction
  const handleUserInteraction = useCallback((action) => {
    setIsAutoPlaying(false);
    action();

    // Resume autoplay after 10 seconds of inactivity
    setTimeout(() => setIsAutoPlaying(true), 10000);
  }, []);

  // Keyboard navigation
  useEffect(() => {
    const handleKeyPress = (e) => {
      if (e.key === "ArrowLeft") {
        handleUserInteraction(prevSlide);
      } else if (e.key === "ArrowRight") {
        handleUserInteraction(nextSlide);
      }
    };

    window.addEventListener("keydown", handleKeyPress);
    return () => window.removeEventListener("keydown", handleKeyPress);
  }, [nextSlide, prevSlide, handleUserInteraction]);

  return (
    <div className="wrapLanding">
      <div
        className="landing_page"
        role="region"
        aria-label="Fashion collection carousel"
        aria-roledescription="carousel"
      >
        {/* Slides */}
        {SLIDES_DATA.map((slide, index) => (
          <div
            key={slide.id}
            className={`slide ${index === currentSlide ? "active" : ""}`}
            role="group"
            aria-roledescription="slide"
            aria-label={`Slide ${index + 1} of ${SLIDES_DATA.length}: ${
              slide.title
            }`}
            aria-hidden={index !== currentSlide}
          >
            {/* Background Image */}
            <div
              className="slide-image"
              style={{ backgroundImage: `url(${slide.image})` }}
              role="img"
              aria-label={slide.alt}
            >
              <div className="slide-overlay" />
            </div>

            {/* Content */}
            <div className="slide-content">
              <div className="content-wrapper">
                <p className="slide-subtitle">{slide.subtitle}</p>
                <h1 className="slide-title">{slide.title}</h1>
                <button
                  className="hero-button"
                  onClick={handleDiscoverClick}
                  aria-label={`Découvrir ${slide.title}`}
                >
                  <span>Découvrir</span>
                  <DiscoverIcon />
                </button>
              </div>
            </div>
          </div>
        ))}

        {/* Navigation Arrows */}
        <button
          className="nav-arrow nav-arrow-left"
          onClick={() => handleUserInteraction(prevSlide)}
          aria-label="Previous slide"
        >
          <ArrowIcon direction="left" />
        </button>

        <button
          className="nav-arrow nav-arrow-right"
          onClick={() => handleUserInteraction(nextSlide)}
          aria-label="Next slide"
        >
          <ArrowIcon direction="right" />
        </button>

        {/* Slide Indicators */}
        <div
          className="slide-indicators"
          role="tablist"
          aria-label="Slide navigation"
        >
          {SLIDES_DATA.map((slide, index) => (
            <button
              key={slide.id}
              className={`indicator ${index === currentSlide ? "active" : ""}`}
              onClick={() => goToSlide(index)}
              role="tab"
              aria-selected={index === currentSlide}
              aria-label={`Go to slide ${index + 1}: ${slide.title}`}
              aria-controls={`slide-${slide.id}`}
            />
          ))}
        </div>

        {/* Screen reader announcement */}
        <div
          className="sr-only"
          role="status"
          aria-live="polite"
          aria-atomic="true"
        >
          Slide {currentSlide + 1} of {SLIDES_DATA.length}:{" "}
          {SLIDES_DATA[currentSlide].title}
        </div>
      </div>
    </div>
  );
}
